(7632655, 1237705, 101668, '<td valign="top">Wonderful!</td>', 'Wonderful!', '2019-06-14 17:32:37.000000', NULL, 1),
(7632656, 1237523, 101668, '<td valign="top">A favourite and a true light in this challenge. Love the control of the light(ing) here, love the subject and the lantern.</td>', 'A favourite and a true light in this challenge. Love the control of the light(ing) here, love the subject and the lantern.', '2019-06-14 17:37:11.000000', NULL, 1),
(7632657, 1237699, 101668, '<td valign="top">O wow, not many images in this challenge show the control of natural light such as this. Real good</td>', 'O wow, not many images in this challenge show the control of natural light such as this. Real good', '2019-06-14 17:38:17.000000', NULL, 1),
(7632658, 1237718, 101668, '<td valign="top">One of 3 9''s from me in this challenge. I love the control of lighting and in this case natural light. Not many photographers succeed in this kind of control, least of all myself. Good work.</td>', 'One of 3 9''s from me in this challenge. I love the control of lighting and in this case natural light. Not many photographers succeed in this kind of control, least of all myself. Good work.', '2019-06-14 17:41:37.000000', NULL, 1),
(7632857, 1237705, 114285, '<td valign="top">Lovely moment..</td>', 'Lovely moment..', '2019-06-17 09:08:08.000000', NULL, 1),
(7632974, 1237350, 32948, '<td valign="top">Brilliant contrast effects</td>', 'Brilliant contrast effects', '2019-06-19 06:20:18.000000', NULL, 1),
(7632975, 1237706, 32948, '<td valign="top">nice</td>', 'nice', '2019-06-19 06:23:06.000000', NULL, 1),
(7633016, 1237553, 173844, '<td valign="top">The encompassing play of light and shadow creates a rich environment which can be entered, and enjoyed, at any point.  I especially like the shadow tones on the flutes and facets of the left hand columns.  I like how the shadows cast by the columns reveal the grain of the tiled floor as it connects up with the vast interior shadow.  How the roof rafters catch the light.  And of course how delicately the spacial recession flutters out.<br/>Personal favorite of the challenge.</td>', 'The encompassing play of light and shadow creates a rich environment which can be entered, and enjoyed, at any point.  I especially like the shadow tones on the flutes and facets of the left hand columns.  I like how the shadows cast by the columns reveal the grain of the tiled floor as it connects up with the vast interior shadow.  How the roof rafters catch the light.  And of course how delicately the spacial recession flutters out.Personal favorite of the challenge.', '2019-06-19 15:13:11.000000', NULL, 1),
(7633059, 1237715, 67145, '<td valign="top">probably as difficult to get the brown as it is to get the blue .. good luck in your attempt .. not voting yet .. :)</td>', 'probably as difficult to get the brown as it is to get the blue .. good luck in your attempt .. not voting yet .. :)', '2019-06-19 16:37:58.000000', NULL, 1),
