(7633076, 1237718, 149964, '<td valign="top">A gorgeous part of the world and this captures it beautifully.</td>', 'A gorgeous part of the world and this captures it beautifully.', '2019-06-19 16:53:24.000000', NULL, 1),
(7633077, 1237350, 149964, '<td valign="top">Wow. Amazing sky and colours.</td>', 'Wow. Amazing sky and colours.', '2019-06-19 16:53:45.000000', NULL, 1),
(7633078, 1237706, 149964, '<td valign="top">Clever in its simplicity. Liken this lots.</td>', 'Clever in its simplicity. Liken this lots.', '2019-06-19 16:54:01.000000', NULL, 1),
(7633079, 1237692, 149964, '<td valign="top">I think it''s what a modern Miss Havisham would have in her room..... like this lots</td>', 'I think it''s what a modern Miss Havisham would have in her room..... like this lots', '2019-06-19 16:55:26.000000', NULL, 1),
(7633080, 1237404, 149964, '<td valign="top">A lovely scene beautifully captured.</td>', 'A lovely scene beautifully captured.', '2019-06-19 16:55:45.000000', NULL, 1),
(7633081, 1237720, 149964, '<td valign="top">Really like all the toing and froing of the lines and the reflections.</td>', 'Really like all the toing and froing of the lines and the reflections.', '2019-06-19 16:56:20.000000', NULL, 1),
(7633082, 1237693, 149964, '<td valign="top">I keep coming back to look at this one. There''s such a lovely story to be told.</td>', 'I keep coming back to look at this one. There''s such a lovely story to be told.', '2019-06-19 16:56:53.000000', NULL, 1),
(7633083, 1237553, 149964, '<td valign="top">Loving the lights and shadows in this.</td>', 'Loving the lights and shadows in this.', '2019-06-19 16:57:10.000000', NULL, 1),
(7633084, 1237705, 173844, '<td valign="top">The sensitive handling of light enhances the tenderness of the portrait.  Beautiful scene, like a visual lullaby.</td>', 'The sensitive handling of light enhances the tenderness of the portrait.  Beautiful scene, like a visual lullaby.', '2019-06-19 17:32:06.000000', NULL, 1),
(7633087, 1237511, 173844, '<td valign="top">Terrific, dramatic sky and receding mountains.  The foreground, which extends half way up the image, is less interesting, in my opinion, aside from the dark and light contrasts and its contribution to great depth of view.  But not enough to keep me from giving this an eight.</td>', 'Terrific, dramatic sky and receding mountains.  The foreground, which extends half way up the image, is less interesting, in my opinion, aside from the dark and light contrasts and its contribution to great depth of view.  But not enough to keep me from giving this an eight.', '2019-06-19 17:45:15.000000', NULL, 1),
(7633089, 1237350, 173844, '<td valign="top">Lovely alpenglow frosting the peaks of this range, complemented by the purplish  layer of clouds behind them.  Then the layer of bright blue covered by descending night, which feels mythically dramatic and significant.  Great view, and lucky you.</td>', 'Lovely alpenglow frosting the peaks of this range, complemented by the purplish  layer of clouds behind them.  Then the layer of bright blue covered by descending night, which feels mythically dramatic and significant.  Great view, and lucky you.', '2019-06-19 17:54:30.000000', NULL, 1),
